    async function approveAndPublishToInstagram() {
      if (window.AR_SERVER && AR_SERVER.mode) return arSnsPublish();
      const d = getSelectedDealer();
      const logBox = document.getElementById('publishLogBox');
      const logLines = document.getElementById('publishLogLines');
      const stepStatus = document.getElementById('publishStepStatus');

      const selectedChannels = [];
      if (document.getElementById('snsCheckIg')?.checked) selectedChannels.push('instagram');
      if (document.getElementById('snsCheckYt')?.checked) selectedChannels.push('youtube');
      if (document.getElementById('snsCheckTt')?.checked) selectedChannels.push('tiktok');
      if (document.getElementById('snsCheckFb')?.checked) selectedChannels.push('facebook');
      if (document.getElementById('snsCheckTh')?.checked) selectedChannels.push('threads');
      if (selectedChannels.length === 0) selectedChannels.push('instagram');

      logBox.classList.remove('hidden');
      logLines.innerHTML = '';
      const schedOn = document.getElementById('snsScheduleEnabled')?.checked;
      const schedAt = document.getElementById('snsScheduleAt')?.value;
      stepStatus.textContent = schedOn && schedAt
        ? `선택된 ${selectedChannels.length}개 SNS 채널 예약 설정 중...`
        : `선택된 ${selectedChannels.length}개 SNS 채널 동시 발행 중...`;

      // 체험 모드: 실제 SNS에는 올라가지 않음 (회원 서버가 켜지면 내 계정을 연결해 실제로 발행)
      const steps = [
        `체험 모드입니다 — 실제 SNS에는 올라가지 않습니다.`,
        `[1] ${d.name} ${d.title} 시안 확인 → 9:16 영상 준비`
      ];
      if (schedOn && schedAt) steps.push(`[예약] ${schedAt.replace('T', ' ')} 자동 발행 예약 확인`);
      const nameOf = { instagram: '인스타그램 릴스', youtube: '유튜브 쇼츠', tiktok: '틱톡', facebook: '페이스북 릴스', threads: '스레드' };
      selectedChannels.forEach((c) => steps.push(`[체험] ${nameOf[c] || c} 발행 흐름 확인`));
      steps.push(`체험 완료 — 실제 발행은 회원 가입 후 SNS 계정을 연결하면 쓸 수 있습니다.`);

      steps.forEach((msg, index) => {
        setTimeout(() => {
          const line = document.createElement('div');
          line.textContent = msg;
          if (index === steps.length - 1) {
            line.className = 'text-emerald-400 font-bold pt-1';
            d.status = 'PUBLISHED';
            stepStatus.textContent = `${selectedChannels.length}개 채널 게시 완료!`;
            renderQuickSelector();
            renderAdminDealerList();
            syncPreviewPanel();
          }
          logLines.appendChild(line);
        }, (index + 1) * 420);
      });
    }

